/* eslint-disable mediawiki/no-storage */
( function () {
	const LOCAL_STORAGE_KEY = 'mw-ext-editorgrowth';
	let store;
	function read() {
		const data = JSON.parse( localStorage.getItem( LOCAL_STORAGE_KEY ) );
		return data && typeof data === 'object' ? data : {};
	}
	function save() {
		localStorage.setItem( LOCAL_STORAGE_KEY, JSON.stringify( store ) );
	}
	try {
		store = read();
		save();
	} catch ( e ) {
		// No localStorage?
		return;
	}
	store.buckets = store.buckets || {};

	// window.mwEditorGrowth is set by some JavaScript generated by the backend
	const state = window.mwEditorGrowth;
	function send( events ) {
		return fetch( state.endpoint, {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify( { id: store.id, events } ),
			keepalive: true
		} );
	}

	function link( name ) {
		// No id = no event generated when logged-out, this is probably an existing user
		if ( store.id && store.linked !== name ) {
			send( [] ).then( ( response ) => {
				if ( response.ok ) {
					// Another tab may have written since this page loaded
					store = read();
					store.linked = name;
					save();
				}
			}, () => {} );
		}
	}

	const conf = window.RLCONF;
	if ( !conf ) {
		// RLCONF should exist on an MW version from the past 5 years, but who knows.
		return;
	}
	// If already registered, report that and bail because we only care about unregistered users
	// Temp accounts are different because we want to keep the old look even after the first edit,
	// though this could be changed
	if ( conf.wgUserName !== null && !conf.wgUserIsTemp ) {
		link( conf.wgUserName );
		return;
	}

	let classes = '';
	for ( const [ name, experiment ] of Object.entries( state.experiments ) ) {
		let bucket = store.buckets[ name ];
		// Bucket not yet assigned or invalid (for whatever reason)
		if ( !experiment.buckets[ bucket ] ) {
			let total = 0;
			for ( const weight of Object.values( experiment.buckets ) ) {
				total += weight;
			}
			let roll = Math.random() * total;
			for ( const [ candidate, weight ] of Object.entries( experiment.buckets ) ) {
				bucket = candidate;
				roll -= weight;
				if ( roll < 0 ) {
					break;
				}
			}
			store.buckets[ name ] = bucket;
		}
		classes += ' ext-editorgrowth-' + name + '-' + bucket;
	}
	save();
	// eslint-disable-next-line mediawiki/class-doc
	document.documentElement.className += classes;

	// For temp accounts, do not record edit events.
	if ( conf.wgUserIsTemp ) {
		link( conf.wgUserName );
		return;
	}
	// In case the user is linked but logged out again.
	if ( store.linked ) {
		return;
	}

	const sent = {};
	// Alternative is to wait for DOMContentLoaded which might still miss some elements,
	// so just listen for all clicks
	document.addEventListener( 'click', ( event ) => {
		const events = [];
		for ( const [ name, experiment ] of Object.entries( state.experiments ) ) {
			for ( const [ action, selector ] of Object.entries( experiment.actions ) ) {
				if ( !sent[ name + action ] && event.target.closest( selector ) ) {
					sent[ name + action ] = true;
					events.push( { experiment: name, bucket: store.buckets[ name ], action } );
				}
			}
		}
		if ( events.length ) {
			if ( !store.id ) {
				// Another tab may have created one since this page loaded
				store.id = read().id;
			}
			if ( !store.id ) {
				const bytes = crypto.getRandomValues( new Uint8Array( 8 ) );
				store.id = Array.from( bytes, ( b ) => b.toString( 16 ).padStart( 2, '0' ) ).join( '' );
				save();
			}
			send( events ).catch( () => {} );
		}
	}, true );
}() );
